            else if (ca_be[i] >= 12'sd1)   y[16*i +: 16] <= {ca_sgn[i], ca_be[i][7:0], ca_cn[i]};
            else                           y[16*i +: 16] <= {ca_sgn[i], 8'd0, ca_sub[i]};
        end
    end
endmodule

